-- Reversible. Simula objetos de Storage; no sube archivos reales ni envía pagos.
do $$
declare a uuid;c uuid;g uuid;o uuid;f uuid;x uuid:=gen_random_uuid();y uuid:=gen_random_uuid();j jsonb;r text;antes_o jsonb;antes_f jsonb;n integer;
begin
 select id into a from public.perfiles where activo and not debe_cambiar_contrasena and rol::text='admin' limit 1;
 select id into c from public.perfiles where activo and not debe_cambiar_contrasena and rol::text='corporativo' limit 1;
 select id into g from public.perfiles where activo and not debe_cambiar_contrasena and rol::text='gerente' limit 1;
 select id,to_jsonb(q) into o,antes_o from public.ordenes_compra q limit 1;
 select id,to_jsonb(q) into f,antes_f from public.facturas q limit 1;
 if a is null or c is null or g is null or o is null or f is null then raise exception 'FALTAN DATOS: admin, corporativo, gerente, orden y factura.';end if;
 select count(*) into n from public.compra_notas where orden_id=o;
 perform set_config('request.jwt.claims',json_build_object('sub',a,'role','authenticated')::text,true);
 set local role authenticated;
 j:=public.preparar_adjunto_compra(x,'orden',o,'ensayo.pdf','pdf','application/pdf',10,repeat('a',64),'Prueba de adjunto');r:=j->>'ruta';
 if j->>'disponible'<>'false' then raise exception 'FALLÓ: reserva';end if;
 if (public.preparar_adjunto_compra(x,'orden',o,'ensayo.pdf','pdf','application/pdf',10,repeat('a',64),'Prueba de adjunto')->>'ruta')<>r then raise exception 'FALLÓ: doble envío';end if;
 perform public.preparar_adjunto_compra(y,'factura',f,'factura.pdf','pdf','application/pdf',10,repeat('b',64),'');
 begin perform public.preparar_adjunto_compra(x,'orden',o,'otro.pdf','pdf','application/pdf',10,repeat('a',64),'');raise exception 'FALLÓ: sobrescritura';exception when others then if sqlerrm like 'FALLÓ:%' then raise;end if;end;
 begin perform public.preparar_adjunto_compra(gen_random_uuid(),'orden',o,'archivo.html','html','text/html',10,repeat('a',64),'');raise exception 'FALLÓ: formato';exception when others then if sqlerrm like 'FALLÓ:%' then raise;end if;end;
 begin perform public.confirmar_adjunto_compra(x);raise exception 'FALLÓ: confirmar sin archivo';exception when others then if sqlerrm like 'FALLÓ:%' then raise;end if;end;
 begin insert into storage.objects(bucket_id,name,metadata) values('adjuntos-compras','sin-reserva.pdf','{}');raise exception 'FALLÓ: subida libre';exception when insufficient_privilege then null;end;
 insert into storage.objects(bucket_id,name,metadata) values('adjuntos-compras',r,'{"size":10,"mimetype":"application/pdf"}');
 perform public.confirmar_adjunto_compra(x);perform public.confirmar_adjunto_compra(x);
 if (select count(*) from public.compra_notas where orden_id=o)<>n+1 then raise exception 'FALLÓ: historial único';end if;
 begin update public.compra_adjuntos set nombre='otro.pdf' where id=x;raise exception 'FALLÓ: escritura directa';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',json_build_object('sub',c,'role','authenticated')::text,true);
 if not exists(select 1 from public.compra_adjuntos where id=x) or exists(select 1 from public.compra_adjuntos where id=y) or not exists(select 1 from storage.objects where bucket_id='adjuntos-compras' and name=r) then raise exception 'FALLÓ: corporativo consulta confirmados';end if;
 begin perform public.confirmar_adjunto_compra(y);raise exception 'FALLÓ: corporativo escribe';exception when others then if sqlerrm like 'FALLÓ:%' then raise;end if;end;
 begin perform public.retirar_adjunto_compra(x,'orden',o,'Archivo equivocado');raise exception 'FALLÓ: corporativo retira';exception when others then if sqlerrm like 'FALLÓ:%' then raise;end if;end;
 perform set_config('request.jwt.claims',json_build_object('sub',a,'role','authenticated')::text,true);
 begin perform public.retirar_adjunto_compra(x,'orden',o,'');raise exception 'FALLÓ: motivo';exception when others then if sqlerrm like 'FALLÓ:%' then raise;end if;end;
 begin perform public.retirar_adjunto_compra(x,'factura',f,'Archivo equivocado');raise exception 'FALLÓ: documento ajeno';exception when others then if sqlerrm like 'FALLÓ:%' then raise;end if;end;
 perform public.retirar_adjunto_compra(x,'orden',o,'Archivo equivocado');
 perform public.retirar_adjunto_compra(x,'orden',o,'Archivo equivocado');
 perform public.confirmar_adjunto_compra(x);
 if exists(select 1 from public.compra_adjuntos where id=x) or exists(select 1 from storage.objects where bucket_id='adjuntos-compras' and name=r) then raise exception 'FALLÓ: retiro visible';end if;
 if (select count(*) from public.compra_notas where orden_id=o)<>n+2 then raise exception 'FALLÓ: retiro duplicado';end if;
 insert into storage.objects(bucket_id,name,metadata) select 'adjuntos-compras',q.ruta,'{"size":10,"mimetype":"application/pdf"}'::jsonb from public.compra_adjuntos q where q.id=y;
 perform public.confirmar_adjunto_compra(y);
 perform public.retirar_adjunto_compra(y,'factura',f,'Factura adjunta incorrecta');
 perform set_config('request.jwt.claims',json_build_object('sub',c,'role','authenticated')::text,true);
 if exists(select 1 from public.compra_adjuntos where id in (x,y)) then raise exception 'FALLÓ: corporativo ve retirado';end if;
 perform set_config('request.jwt.claims',json_build_object('sub',g,'role','authenticated')::text,true);
 if exists(select 1 from public.compra_adjuntos where id=x) or exists(select 1 from storage.objects where bucket_id='adjuntos-compras' and name=r) then raise exception 'FALLÓ: gerente acceso';end if;
 reset role;
 if not exists(select 1 from public.compra_adjuntos where id=x and retirado_por=a and retiro_motivo='Archivo equivocado') or not exists(select 1 from storage.objects where bucket_id='adjuntos-compras' and name=r) then raise exception 'FALLÓ: original conservado';end if;
 if has_function_privilege('anon','public.retirar_adjunto_compra(uuid,text,uuid,text)','execute') then raise exception 'FALLÓ: retiro anónimo';end if;
 if antes_o is distinct from (select to_jsonb(q) from public.ordenes_compra q where id=o) or antes_f is distinct from (select to_jsonb(q) from public.facturas q where id=f) then raise exception 'FALLÓ: modificó documento';end if;
 if (select public from storage.buckets where id='adjuntos-compras') or has_function_privilege('anon','public.confirmar_adjunto_compra(uuid)','execute') then raise exception 'FALLÓ: público';end if;
 raise exception 'PRUEBAS OK — retiro de adjuntos · motivo y confirmación · orden y factura · historial único · doble envío · archivo original conservado · sin descarga del retirado · conserva documento · corporativo consulta · sin escritura directa · anónimo sin ejecución';
end $$;
